<template><view class="page"><view class="wrap"><MobileHeader title="控制台"/><view class="heading"><text class="section-title">最近通知</text><text class="badge" role="button" @tap="open('/pages/notifications/index')">全部</text></view><view class="card"><view v-for="notice in notices" :key="notice.id" class="row" @tap="open('/pages/notifications/index')"><text>{{notice.templateContent}}</text><AppIcon name="chevron-right" :size="16" color="#8791a4"/></view><view v-if="!notices.length" class="empty">{{busy?'正在加载':error||(session.identity?'暂无未读通知':'暂无通知')}}</view></view></view><TabBar current="workbench"/></view></template>
<script setup lang="ts">
import {ref} from 'vue';import {onShow,onUnload} from '@dcloudio/uni-app';import MobileHeader from '@/components/MobileHeader.vue';import TabBar from '@/components/TabBar.vue';import AppIcon from '@/components/AppIcon.vue';import {client,session} from '@/platform';
const notices=ref<any[]>([]),busy=ref(false),error=ref('');let generation=0;
function open(url:string){uni.navigateTo({url});}
onUnload(()=>{generation++;});
onShow(async()=>{const rev=++generation;notices.value=[];error.value='';if(!session.identity){busy.value=false;return;}busy.value=true;try{const rows=await client.request('GET','/admin-api/system/notify-message/get-unread-list?size=3');if(rev===generation)notices.value=rows;}catch{if(rev===generation)error.value='通知暂时不可用';}finally{if(rev===generation)busy.value=false;}});
</script>
<style scoped>.page{min-height:100vh;background:#f7f8fc;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.wrap{max-width:500px;margin:auto;padding:0 15px}.section-title{font-size:17px;font-weight:600}.heading{margin:26px 3px 0;display:flex;justify-content:space-between}.card{background:#fff;border-radius:18px;padding:18px;margin-top:14px;box-shadow:0 6px 16px rgba(20,31,51,.06)}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid #eef1f6}.row:last-child{border:0}.empty{padding:36px 0;text-align:center;color:#8791a4;font-size:14px}.badge{color:#294fdb;font-size:12px}</style>